const W = 1920, H = 1080;
const RED = '#c8323c', GOLD = '#e8b65c', INK = '#0c0a09', PAPER = '#f4ead8', JADE = '#7fb7a4';
const sm = (v: number) => {const p = clamp(v); return p * p * (3 - 2 * p);};
const out3 = (v: number) => 1 - Math.pow(1 - clamp(v), 3);
/** 区间窗：a 起淡入、b 起淡出（秒）。 */
const win = (t: number, a: number, b: number, f = .25) => sm((t - a) / f) * (1 - sm((t - b) / f));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;

// 随包样片（S107）没有素材 ID：prepare.py --sample 把本幕用到的底图以 data URI 内联在这里；制作任务里为空。
const MEDIA: Record<string, string> = {"dust":"release-assets/e27d0ed2ba1fcb9f4eab176df363ff25c29109b8c41a076adb5ba08929ab1761.webp"};
/** 素材：先用素材槽（制作任务），再用内联底图（样片）；视频槽在样片里缺省，调用处退回同名底图。 */
function slot(props: SceneInput, name: string): any {
  return props.assets[name] ?? (MEDIA[name] ? {src: MEDIA[name], kind: 'image'} : undefined);
}

// 画面文字都是各幕 meta.params 声明的内容参数（默认值是中文原文），语言版本只换参数、不换代码。
// 没有汉字的文字按西文排：衬线字体横排、按估算宽度对齐与缩放（估算是纯函数，渲染结果确定）。
const SERIF = 'Georgia, "Times New Roman", "Noto Serif", serif';
const isLatin = (text: string) => !/[㐀-鿿]/.test(text);
const latinWidth = (text: string, size: number, spacing = 0) => Array.from(text).reduce((w, ch) => w + spacing + size *
  (ch === ' ' ? .25 : /[A-Z]/.test(ch) ? .7 : /[il.,'’:;!|·]/.test(ch) ? .3 : /[mwMW]/.test(ch) ? .8 : /[0-9]/.test(ch) ? .58 : .5), 0);
/** 文字参数：props 里写了就用，否则用本幕 meta 的默认值。 */
function txt(props: SceneInput, key: string): string {
  const value = props.params[key];
  return typeof value === 'string' ? value : String((meta as any).params?.[key]?.default ?? '');
}
/** 列表参数（文字或 {label, cue} 对象）。 */
function list<T = any>(props: SceneInput, key: string): T[] {
  const value = props.params[key];
  return Array.isArray(value) && value.length ? value : (meta as any).params?.[key]?.default ?? [];
}
/** “第 {n} 次” → “第 3 次”。 */
const fmt = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (_, key) => String(values[key] ?? ''));
/** 天气名：names 列表 [{kind, label}] 优先，缺了用中文原名；都没有时返回 undefined。 */
const weatherName = (props: SceneInput, kind: string): string | undefined => list<{kind: string; label: string}>(props, 'names').find(item => item?.kind === kind)?.label ?? WEATHER_NAME[kind];

/** 句子时间：cue 找不到时退回句首/幕首，保证改文案后画面不丢。 */
function cues(props: SceneInput) {
  const s = useScene(props);
  const at = (phrase: string, fallback = 0) => s.cue(phrase) ?? fallback;
  const start = (i: number, fallback = 0) => s.sentence(i)?.start ?? fallback;
  const end = (i: number, fallback = s.seconds) => s.sentence(i)?.end ?? fallback;
  // 旁白最后一句的句尾：西文长句会被管线按分句拆成几段，“整段旁白念完”不能写成 end(0)。
  const endAll = (fallback = s.seconds) => s.sentence(Number.MAX_SAFE_INTEGER)?.end ?? fallback;
  return {s, t: s.t, at, start, end, endAll, dur: s.seconds};
}

/** 满幅底图/视频 + 运镜（scale/位移随整幕缓动），filter 做调色。 */
function Plate({asset, frame, p, from = [1.04, 0, 0], to = [1.14, -30, -12], filter = '', opacity = 1, origin = '50% 50%'}:
  {asset: any; frame: number; p: number; from?: number[]; to?: number[]; filter?: string; opacity?: number; origin?: string}) {
  const k = easeInOut(p);
  const s = mix(from[0], to[0], k), x = mix(from[1], to[1], k), y = mix(from[2], to[2], k);
  return <div style={{position: 'absolute', inset: 0, overflow: 'hidden', opacity}}>
    <div style={{position: 'absolute', inset: 0, transform: `translate(${x}px, ${y}px) scale(${s})`, transformOrigin: origin, filter}}>
      <Media asset={asset} frame={frame} fit="cover" style={{width: '100%', height: '100%', objectFit: 'cover'}} />
    </div>
  </div>;
}

/** 毛笔字：每字按横扫遮罩显现；p 为整句进度 0→1。西文（没有汉字）改用衬线字整行横扫：x 按 align 对齐，超过 maxWidth 等比缩小。 */
function Brush({text, x, y, size, fill = PAPER, p = 1, vertical = false, id, gap = .96, shadow = true, align = 'start', maxWidth = 0, scale = .66, italic = false}:
  {text: string; x: number; y: number; size: number; fill?: string; p?: number; vertical?: boolean; id: string; gap?: number; shadow?: boolean;
    align?: 'start' | 'middle' | 'end'; maxWidth?: number; scale?: number; italic?: boolean}) {
  if (!text) return null;
  if (isLatin(text)) {
    const natural = latinWidth(text, size * scale, size * .01), k = maxWidth && natural > maxWidth ? maxWidth / natural : 1;
    const font = size * scale * k, width = natural * k, left = align === 'middle' ? x - width / 2 : align === 'end' ? x - width : x;
    const reveal = clamp(p), baseline = y + size * .5 + font * .36;
    if (reveal <= 0) return null;
    return <g style={shadow ? {filter: 'drop-shadow(0 6px 18px rgba(0,0,0,.65))'} : undefined}>
      <defs><clipPath id={`${id}-l`}><rect x={left - font * .3} y={baseline - font * 1.1} width={(width + font * .6) * reveal} height={font * 1.5} /></clipPath></defs>
      <text x={left} y={baseline} fontFamily={SERIF} fontSize={font} fontStyle={italic ? 'italic' : undefined} letterSpacing={size * .01 * k}
        fill={fill} clipPath={`url(#${id}-l)`}>{text}</text>
    </g>;
  }
  const chars = Array.from(text);
  return <g style={shadow ? {filter: 'drop-shadow(0 6px 18px rgba(0,0,0,.65))'} : undefined}>{chars.map((ch, i) => {
    const q = clamp(p * chars.length - i);
    if (q <= 0 || !GLYPHS[ch]) return null;
    const ox = x + (vertical ? 0 : i * size * gap), oy = y + (vertical ? i * size * 1.06 : 0);
    return <g key={i} transform={`translate(${ox} ${oy}) scale(${size / 1000})`}>
      <defs><mask id={`${id}-${i}`} maskUnits="userSpaceOnUse" x="-150" y="-150" width="1300" height="1300">
        <path d="M-80 80 L1040 80 L-80 320 L1040 320 L-80 550 L1040 550 L-80 790 L1040 790 L-80 1030 L1040 1030"
          fill="none" stroke="white" strokeWidth="255" pathLength="100" strokeDasharray="100" strokeDashoffset={100 * (1 - q)} />
      </mask></defs>
      <path d={GLYPHS[ch]} fill={fill} mask={`url(#${id}-${i})`} />
    </g>;
  })}</g>;
}
/** 整版 SVG 画布（幕坐标 1920×1080）。 */
const Svg = ({children, style}: {children: any; style?: any}) =>
  <svg viewBox={`0 0 ${W} ${H}`} width="100%" height="100%" style={{position: 'absolute', inset: 0, overflow: 'visible', ...style}}>{children}</svg>;

/** 朱印：落下时由大到小砸实。 */
function Seal({x, y, text, size = 120, p, id, color = RED}: {x: number; y: number; text: string; size?: number; p: number; id: string; color?: string}) {
  if (p <= 0 || !text) return null;
  const k = out3(p), sc = 1 + 1.6 * (1 - k), chars = Array.from(text);
  if (isLatin(text)) {
    // 西文朱印：大写衬线字压在印框里，按宽度缩到框内。
    const label = text.toUpperCase(), font = Math.min(size * .36, size * .8 / Math.max(.01, latinWidth(label, 1, .02)));
    return <g transform={`translate(${x} ${y}) scale(${sc}) rotate(${-4 + 4 * k})`} opacity={clamp(p * 3)}>
      <rect x={-size / 2} y={-size * .32} width={size} height={size * .64} rx={size * .06} fill={color} style={{filter: 'url(#rough)'}} />
      <rect x={-size / 2 + 6} y={-size * .32 + 6} width={size - 12} height={size * .64 - 12} rx={size * .04} fill="none" stroke={PAPER} strokeWidth={3} opacity={.7} />
      <text x={0} y={font * .36} textAnchor="middle" fontFamily={SERIF} fontWeight={700} fontSize={font} letterSpacing={font * .02} fill={PAPER}>{label}</text>
    </g>;
  }
  const cols = chars.length > 2 ? 2 : 1, rows = Math.ceil(chars.length / cols), cell = size / Math.max(cols, rows);
  return <g transform={`translate(${x} ${y}) scale(${sc}) rotate(${-4 + 4 * k})`} opacity={clamp(p * 3)}>
    <rect x={-size / 2} y={-size / 2} width={size} height={size} rx={size * .06} fill={color} style={{filter: 'url(#rough)'}} />
    <rect x={-size / 2 + 7} y={-size / 2 + 7} width={size - 14} height={size - 14} rx={size * .04} fill="none" stroke={PAPER} strokeWidth={3} opacity={.7} />
    {chars.map((ch, i) => {
      const col = cols - 1 - Math.floor(i / rows), row = i % rows;
      return <Brush key={i} text={ch} id={`${id}-${i}`} size={cell * .78} fill={PAPER} shadow={false}
        x={-size / 2 + col * cell + cell * .11} y={-size / 2 + row * cell + cell * .1} />;
    })}
  </g>;
}
const Defs = () => <defs>
  <filter id="rough"><feTurbulence type="fractalNoise" baseFrequency=".035" numOctaves="2" seed="7" />
    <feDisplacementMap in="SourceGraphic" scale="9" xChannelSelector="R" yChannelSelector="G" /></filter>
</defs>;

/** 天气：sun 烈日 / rain 暴雨 / fog 山雾 / night 黑夜 / snow 雪夜 / clear 原样。grade 给底图，overlay 叠在上面。 */
const GRADES: Record<string, string> = {
  clear: '',
  sun: 'brightness(1.12) saturate(1.35) contrast(1.06) sepia(.18)',
  rain: 'brightness(.6) saturate(.55) contrast(1.12) hue-rotate(-8deg)',
  fog: 'brightness(1.02) saturate(.4) contrast(.72)',
  night: 'brightness(.36) saturate(.55) contrast(1.2) hue-rotate(18deg)',
  snow: 'brightness(.55) saturate(.35) contrast(1.1)',
  dusk: 'brightness(.85) saturate(1.2) sepia(.35) contrast(1.05)',
};
const WEATHER_NAME: Record<string, string> = {sun: '烈日', rain: '暴雨', fog: '山雾', night: '黑夜', snow: '风雪', dusk: '黄昏', clear: '晴'};

/** 雨丝（canvas，按帧确定）。 */
function Rain({frame, amount = 1, angle = .22, seed = 3, opacity = 1}: {frame: number; amount?: number; angle?: number; seed?: number; opacity?: number}) {
  const r = seeded(seed), drops = Array.from({length: 520}, () => ({x: r() * W * 1.3, y: r() * H, l: 30 + r() * 70, v: 1500 + r() * 1300, z: r()}));
  const ref = useCanvas(frame, (c, f) => {
    const t = f / 30;
    c.lineCap = 'round';
    drops.forEach((d, i) => {
      if (i / drops.length > amount) return;
      const y = (d.y + d.v * t) % (H + 120) - 60, x = (d.x - y * angle) % (W * 1.3) - W * .15;
      c.strokeStyle = `rgba(205,220,235,${.18 + .4 * d.z})`; c.lineWidth = .8 + 1.8 * d.z;
      c.beginPath(); c.moveTo(x, y); c.lineTo(x - d.l * angle, y + d.l); c.stroke();
    });
  });
  return <canvas ref={ref} width={W} height={H} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', opacity}} />;
}
/** 雪/灰/火星/红尘：缓慢飘落或上扬的粒子。 */
function Motes({frame, kind = 'snow', amount = 1, seed = 5, opacity = 1}: {frame: number; kind?: 'snow' | 'ash' | 'ember' | 'dust' | 'pollen'; amount?: number; seed?: number; opacity?: number}) {
  const r = seeded(seed + kind.length), n = 260, motes = Array.from({length: n}, () => ({x: r() * W, y: r() * H, s: r(), ph: r() * 6.28}));
  const ref = useCanvas(frame, (c, f) => {
    const t = f / 30;
    motes.forEach((m, i) => {
      if (i / n > amount) return;
      const up = kind === 'ember' || kind === 'pollen' ? -1 : 1, speed = kind === 'snow' ? 70 + 90 * m.s : kind === 'dust' ? 25 : 45 + 60 * m.s;
      const y = ((m.y + up * speed * t) % H + H) % H, x = (m.x + Math.sin(t * 1.3 + m.ph) * 28 + (kind === 'dust' ? 160 * t * (0.4 + m.s) : 20 * t)) % W;
      const size = kind === 'snow' ? 1.5 + 3.5 * m.s : kind === 'ember' ? 1.2 + 2.4 * m.s : 1 + 2.2 * m.s;
      const color = kind === 'ember' ? `rgba(255,${120 + 80 * m.s},60,${.5 + .5 * Math.sin(t * 6 + m.ph) ** 2})`
        : kind === 'ash' ? `rgba(70,64,60,${.35 + .4 * m.s})` : kind === 'dust' ? `rgba(220,120,90,${.25 + .35 * m.s})`
        : kind === 'pollen' ? `rgba(255,226,150,${.3 + .5 * m.s})` : `rgba(245,248,255,${.45 + .5 * m.s})`;
      c.fillStyle = color; c.beginPath(); c.arc(x, y, size, 0, 6.283); c.fill();
    });
  });
  return <canvas ref={ref} width={W} height={H} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', opacity}} />;
}
/** 山雾：几层横向漂移的柔光雾带。 */
function Fog({t, amount = 1, tint = '232,236,238'}: {t: number; amount?: number; tint?: string}) {
  return <div style={{position: 'absolute', inset: 0, opacity: amount, pointerEvents: 'none'}}>
    {[0, 1, 2, 3].map(i => <div key={i} style={{position: 'absolute', left: -600 + ((t * (40 + i * 25) + i * 500) % 900), top: 120 + i * 210, width: 3200, height: 420,
      background: `radial-gradient(ellipse at center, rgba(${tint},${.55 - i * .08}) 0%, rgba(${tint},0) 70%)`, filter: 'blur(30px)'}} />)}
    <div style={{position: 'absolute', inset: 0, background: `linear-gradient(180deg, rgba(${tint},.25), rgba(${tint},.55))`}} />
  </div>;
}
/** 烈日：右上光源、眩光与镜头光斑。 */
function Sun({t, amount = 1, x = 1500, y = 160}: {t: number; amount?: number; x?: number; y?: number}) {
  const pulse = 1 + .04 * Math.sin(t * 2.2);
  return <div style={{position: 'absolute', inset: 0, opacity: amount, mixBlendMode: 'screen', pointerEvents: 'none'}}>
    <div style={{position: 'absolute', left: x - 700 * pulse, top: y - 700 * pulse, width: 1400 * pulse, height: 1400 * pulse,
      background: 'radial-gradient(circle, rgba(255,246,214,.95) 0%, rgba(255,196,96,.45) 18%, rgba(255,140,40,.12) 45%, rgba(255,120,0,0) 70%)'}} />
    {[.35, .6, .82].map((k, i) => <div key={i} style={{position: 'absolute', left: mix(x, W - x, k) - 40 - i * 30, top: mix(y, H - y, k) - 40 - i * 30,
      width: 80 + i * 60, height: 80 + i * 60, borderRadius: '50%', background: `rgba(255,${200 - i * 30},${120 + i * 40},.12)`}} />)}
    <div style={{position: 'absolute', inset: 0, background: 'linear-gradient(200deg, rgba(255,170,60,.28), rgba(255,120,30,0) 60%)'}} />
  </div>;
}
/** 黑夜：深蓝压暗、月轮、星点与暖色火光。 */
function Night({t, amount = 1, torch = true}: {t: number; amount?: number; torch?: boolean}) {
  const r = seeded(91), stars = Array.from({length: 70}, () => ({x: r() * W, y: r() * 360, s: r()}));
  const flicker = .75 + .25 * Math.sin(t * 13) * Math.sin(t * 7.3 + 1);
  return <div style={{position: 'absolute', inset: 0, opacity: amount, pointerEvents: 'none'}}>
    <div style={{position: 'absolute', inset: 0, background: 'linear-gradient(180deg, rgba(10,22,52,.55), rgba(6,10,24,.35))', mixBlendMode: 'multiply'}} />
    <Svg>{stars.map((s, i) => <circle key={i} cx={s.x} cy={s.y} r={.6 + 1.4 * s.s} fill="#dfe8ff" opacity={.3 + .6 * Math.abs(Math.sin(t * 2 + i))} />)}
      <circle cx={1580} cy={150} r={58} fill="#f3efe0" opacity={.92} style={{filter: 'drop-shadow(0 0 40px rgba(240,236,210,.8))'}} /></Svg>
    {torch && <div style={{position: 'absolute', inset: 0, background: `radial-gradient(ellipse at 40% 85%, rgba(255,140,50,${.32 * flicker}) 0%, rgba(255,120,40,0) 55%)`, mixBlendMode: 'screen'}} />}
  </div>;
}
/** 闪电：at 时刻起 0.35 秒的双闪 + 折线电光。 */
function Lightning({t, at, x = 1200}: {t: number; at: number; x?: number}) {
  const d = t - at;
  if (d < 0 || d > .45) return null;
  const flash = d < .08 ? 1 : d < .16 ? .25 : d < .24 ? .8 : Math.max(0, 1 - (d - .24) / .2) * .5;
  const r = seeded(Math.round(at * 100)), pts: string[] = [];
  let px = x, py = 0;
  while (py < 640) {pts.push(`${px},${py}`); px += (r() - .5) * 120; py += 40 + r() * 60;}
  return <>
    <div style={{position: 'absolute', inset: 0, background: `rgba(220,230,255,${.55 * flash})`, mixBlendMode: 'screen'}} />
    <Svg><polyline points={pts.join(' ')} fill="none" stroke="#f4f7ff" strokeWidth={4} opacity={flash} style={{filter: 'drop-shadow(0 0 16px #b8c8ff)'}} /></Svg>
  </>;
}
/** 天气层合成：weather 名称 + 强度。 */
function WeatherLayer({kind, t, frame, amount = 1, seed = 1}: {kind: string; t: number; frame: number; amount?: number; seed?: number}) {
  if (amount <= 0) return null;
  if (kind === 'sun') return <><Sun t={t} amount={amount} /><Motes frame={frame} kind="pollen" amount={.4} opacity={amount * .8} seed={seed} /></>;
  if (kind === 'rain') return <><div style={{position: 'absolute', inset: 0, background: 'rgba(30,48,70,.35)', mixBlendMode: 'multiply', opacity: amount}} />
    <Rain frame={frame} amount={amount} seed={seed} /><Fog t={t} amount={.25 * amount} tint="150,165,180" /></>;
  if (kind === 'fog') return <Fog t={t} amount={amount} />;
  if (kind === 'night') return <Night t={t} amount={amount} />;
  if (kind === 'snow') return <><Night t={t} amount={amount * .6} torch={false} /><Motes frame={frame} kind="snow" amount={amount} seed={seed} /></>;
  return null;
}

/** 暗角。（试过低分辨率噪声放大做胶片颗粒：GPU 插值与叠加混合两次渲染不一致，交付检查判 CODE_NONDETERMINISTIC，已去掉。） */
function Finish({vignette = .55}: {frame?: number; vignette?: number}) {
  return <div style={{position: 'absolute', inset: 0, background: `radial-gradient(ellipse at center, rgba(0,0,0,0) 45%, rgba(0,0,0,${vignette}) 100%)`}} />;
}
/** 镜头震动（秒内衰减）。 */
const shake = (t: number, at: number, power = 18, len = .5) => {
  const d = t - at;
  if (d < 0 || d > len) return 'none';
  const k = (1 - d / len) * power;
  return `translate(${Math.sin(d * 90) * k}px, ${Math.cos(d * 70) * k * .7}px)`;
};
/** 小字说明（宿主正文字体；西文字距收窄）。serif 用于诗句译文。 */
const Note = ({children, x, y, size = 26, color = 'rgba(244,234,216,.78)', opacity = 1, align = 'left', fonts, spacing = 4, serif = false}: any) =>
  !children && children !== 0 ? null : <div style={{position: 'absolute', left: align === 'right' ? undefined : x, right: align === 'right' ? W - x : undefined, top: y,
    fontFamily: serif ? SERIF : fonts?.text, fontStyle: serif ? 'italic' : undefined, textAlign: align === 'right' ? 'right' : 'left',
    fontSize: size, letterSpacing: typeof children === 'string' && isLatin(children) ? Math.min(spacing, 1) : spacing, color, opacity, textShadow: '0 2px 10px rgba(0,0,0,.8)', whiteSpace: 'nowrap'}}>{children}</div>;
/** 幕首/幕末黑场。 */
const fadeEdges = (t: number, dur: number, inS = .2, outS = .18) => Math.min(sm(t / inS), sm((dur - t) / outS));

// 开场：红尘奔马（Veo 图生视频，缺失时退回底图）+ 杜牧诗竖排落笔。诗句是书法画面，其他语言版本保留原诗、在旁边加译文。
export const meta = {
  params: {
    line1: {label: '诗句一', type: 'text', default: '一骑红尘妃子笑', maxLength: 8},
    line2: {label: '诗句二', type: 'text', default: '无人知是荔枝来', maxLength: 8},
    seal: {label: '落款印', type: 'text', default: '杜牧', maxLength: 4},
    translation: {label: '译文', type: 'list', default: [], max: 2, maxLength: 60, help: '每行对应一句诗，写在书法旁；中文版留空'},
    credit: {label: '出处', type: 'text', default: '唐 · 杜牧《过华清宫》', maxLength: 60},
  },
};
export default function Poem(props: SceneInput) {
  const {t, start, endAll, dur} = cues(props);
  const a = start(0, .2), b = endAll(dur - .4), mid = a + (b - a) * .5;
  const line1 = clamp((t - a) / ((mid - a) * .9)), line2 = clamp((t - mid) / ((b - mid) * .9));
  const clip = slot(props, 'dust-clip') ?? slot(props, 'dust');
  const translation = list<string>(props, 'translation').map(String);
  return <div style={{position: 'absolute', inset: 0, background: INK, overflow: 'hidden', opacity: fadeEdges(t, dur, .5, .08)}}>
    <Plate asset={clip} frame={props.frame} p={t / dur} from={[1.02, 0, 0]} to={[1.1, -20, 0]} filter="contrast(1.08) saturate(1.1)" />
    <div style={{position: 'absolute', inset: 0, background: 'linear-gradient(90deg, rgba(0,0,0,0) 45%, rgba(8,4,2,.72) 100%)'}} />
    <Motes frame={props.frame} kind="dust" amount={.9} seed={4} />
    <Svg><Defs />
      <Brush id="p1" text={txt(props, 'line1')} x={1610} y={150} size={92} vertical p={line1} />
      <Brush id="p2" text={txt(props, 'line2')} x={1470} y={150} size={92} vertical p={line2} fill="#f0c9a8" />
      <Seal id="ps" text={txt(props, 'seal')} x={1395} y={930} size={70} p={clamp((t - b + .3) / .3)} />
    </Svg>
    {translation.map((line, i) => <Note key={i} fonts={props.fonts} serif x={1400} y={430 + i * 64} size={40} align="right" color={i ? '#f0c9a8' : PAPER}
      opacity={sm(((i ? line2 : line1) - .15) / .35)}>{line}</Note>)}
    <Note fonts={props.fonts} x={1360} y={1000} size={22} align="right" opacity={sm((t - b + .2) / .4) * .8}>{txt(props, 'credit')}</Note>
    <Finish frame={props.frame} />
  </div>;
}
